const sourceQuotes=[{"sourceEn": "Isn't it splendid to think of all the things there are to find out about?", "sourceKo": "아직 알아갈 것이 이렇게 많다는 건 참 멋진 일이야."}, {"sourceEn": "It just makes me feel glad to be alive—it's such an interesting world.", "sourceKo": "세상은 궁금한 것으로 가득해서, 살아 있다는 사실만으로도 기뻐질 때가 있어."}, {"sourceEn": "There'd be no scope for imagination then, would there?", "sourceKo": "모든 걸 이미 안다면 상상할 여백도 사라지겠지."}, {"sourceEn": "When you are imagining, you might as well imagine something worth while.", "sourceKo": "상상할 거라면 마음을 조금 더 환하게 만드는 것을 상상해도 좋아."}, {"sourceEn": "How are you going to find out about things if you don't ask questions?", "sourceKo": "궁금한 건 묻는 순간부터 내 세계가 넓어져."}, {"sourceEn": "I'm so glad I live in a world where there are Octobers.", "sourceKo": "계절마다 기다릴 아름다움이 있다는 건 참 다행이야."}, {"sourceEn": "Tomorrow is a new day with no mistakes in it yet.", "sourceKo": "내일은 아직 어떤 실수도 시작되지 않은 새로운 하루야."}, {"sourceEn": "It's delightful when your imaginations come true, isn't it?", "sourceKo": "마음속으로 그리던 일이 현실이 되는 순간은 참 근사해."}, {"sourceEn": "Kindred spirits are not so scarce as I used to think.", "sourceKo": "나와 마음이 통하는 사람은 생각보다 세상에 더 많이 있어."}, {"sourceEn": "It's splendid to find out there are so many of them in the world.", "sourceKo": "좋은 인연이 세상 곳곳에 있다는 걸 발견하는 건 큰 기쁨이야."}, {"sourceEn": "I'm not a bit changed—not really. I'm only just pruned down and branched out.", "sourceKo": "나는 사라진 게 아니라, 조금 다듬어지고 더 넓게 자란 거야."}, {"sourceEn": "There's such a lot of different Annes in me.", "sourceKo": "내 안에는 한 가지 모습만 있는 게 아니야. 여러 모습의 내가 함께 살아."}, {"sourceEn": "It's been my experience that you can nearly always enjoy things if you make up your mind firmly that you will.", "sourceKo": "마음을 정하면 평범한 순간에서도 즐거움을 찾아낼 수 있어."}, {"sourceEn": "I never can be in the morning. Isn't it a splendid thing that there are mornings?", "sourceKo": "아침은 어제의 무게를 조금 내려놓게 해주는 새 출발이야."}, {"sourceEn": "I'm so glad it's a sunshiny morning.", "sourceKo": "햇살 좋은 아침을 기뻐하는 마음도 충분히 소중해."}, {"sourceEn": "It's so much more romantic to end a story with a funeral than a wedding.", "sourceKo": "이야기는 예상과 다르게 흘러가도 그 자체로 특별해질 수 있어."}, {"sourceEn": "I don't know what lies around the bend, but I'm going to believe that the best does.", "sourceKo": "앞에 무엇이 있는지 몰라도 좋은 것을 믿으며 걸어갈 수 있어."}, {"sourceEn": "I shall give life here my best, and I believe it will give its best to me in return.", "sourceKo": "내가 오늘을 진심으로 살아내면 삶도 언젠가 좋은 것으로 답해줄 거라 믿어."}, {"sourceEn": "It is ever so much easier to be good if your clothes are fashionable.", "sourceKo": "작은 기분 전환이 마음을 가볍게 해주는 날도 있어."}, {"sourceEn": "Somehow, little dream girls are not satisfying after a real friend.", "sourceKo": "상상도 위로가 되지만 진짜 사람의 따뜻함은 또 다른 힘이 있어."}, {"sourceEn": "It's all very well to read about sorrows and imagine yourself living through them heroically.", "sourceKo": "힘든 일을 멋지게 견디는 건 상상보다 어렵지만, 그래서 실제 용기는 더 값져."}, {"sourceEn": "But the worst of imagining things is that the time comes when you have to stop and that hurts.", "sourceKo": "좋은 상상이 끝날 때 아쉬운 건, 그만큼 마음을 다해 즐겼다는 뜻이야."}, {"sourceEn": "I guess ice-cream is one of those things that are beyond imagination.", "sourceKo": "어떤 기쁨은 상상보다 직접 누릴 때 더 달콤해."}, {"sourceEn": "There are so many things in this room and all so splendid that there is no scope for imagination.", "sourceKo": "가득 채우는 것보다 상상할 여백을 남기는 것도 아름다워."}, {"sourceEn": "That is one consolation when you are poor—there are so many more things you can imagine about.", "sourceKo": "부족한 순간에도 마음은 새로운 가능성을 그릴 수 있어."}, {"sourceEn": "If you have big ideas you have to use big words to express them, haven't you?", "sourceKo": "큰 생각을 가진 사람이라면 자기 방식으로 당당하게 표현해도 좋아."}, {"sourceEn": "Don't you feel as if you just loved the world on a morning like this?", "sourceKo": "어떤 아침은 이유 없이 세상을 좋아하게 만들어."}, {"sourceEn": "I can hear the brook laughing all the way up here.", "sourceKo": "귀 기울이면 평범한 풍경에서도 웃음소리 같은 기쁨을 발견할 수 있어."}, {"sourceEn": "I'm glad it's a beautiful morning. But I like rainy mornings real well, too.", "sourceKo": "맑은 날뿐 아니라 비 오는 날에도 그날만의 아름다움이 있어."}];
